import{z as n,x as d,o as A,c as i,q as E,j as o,D as e,d as r,s as l,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"DAC / MAC / RBAC","description":"","frontmatter":{"title":"DAC / MAC / RBAC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dac-mac-rbac.md","filePath":"cs/dac-mac-rbac.md","lastUpdated":1791063341000}'),C={name:"cs/dac-mac-rbac.md"};function c(p,a,m,D,u,h){const B=d("Mermaid");return A(),i("div",null,[a[2]||(a[2]=E('<h1 id="dac-mac-rbac" tabindex="-1">DAC / MAC / RBAC <a class="header-anchor" href="#dac-mac-rbac" aria-label="Permalink to &quot;DAC / MAC / RBAC&quot;">​</a></h1><div class="epigraph"><p>自主访问控制让属主改 ACL；强制访问控制用标签策略挡住「自愿泄露」；角色把权限聚成岗位而不是每人一条。</p><footer>—— 据 Lampson 保护矩阵；Bell–LaPadula 对照；Sandhu 对 RBAC；Saltzer and Schroeder</footer></div><p><a href="/cs/acl-least-priv">上一课</a>给出主体–客体–操作与最小特权。本课不重画矩阵。缺口是政策谁来写：属主（DAC）、系统标签（MAC）、岗位角色（RBAC）。能力下一课对照矩阵的另一种存放。三者都能表达同一矩阵的子集，失败模式不同。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>最小特权课留下矩阵。Unix 文件 mode 是 DAC：属主可 chmod 把读权给别人，木马也能借属主去改。MAC：级别与范畴，写不上读下一类规则（教学用 BLP 直觉），用户不能自愿改标签以泄密。RBAC：权限授给角色，人授角色，便于岗位变动。缺口是<strong>三种政策来源</strong>。</p><p><span class="marginnote">直觉类比：DAC 像&quot;门钥匙我自己借人&quot;——属主有权借，也可能被骗着借；木马顶着属主身份跑一段代码，就能名正言顺把密件转发出去。MAC 干的事就是把&quot;借钥匙&quot;这个环节本身没收。</span></p><p><span class="marginnote">MLS 的形式模型有争议与例外。主干只取「策略不由文件属主随意改」这一层。RBAC 可叠在 DAC 上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现：DAC 用 ACL 或 mode；MAC 用标签 + 引用监视器；RBAC 用角色表。检查总在引用监视器，与<a href="/cs/kernel-user">内核与用户态</a> 一致。本课不把 SELinux 类型列表当必背。</p><p><span class="marginnote">引用监视器可以想成&quot;所有门都归同一个保安&quot;：谁想碰客体都必经这一个检查点，且它不可绕过、不可收买（由内核实现）。检查集中在一处，事后审计才有单点可查。</span></p>',10)),(A(),o(s,null,{default:e(()=>[l(B,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20MAT%5B%22%E4%BF%9D%E6%8A%A4%E7%9F%A9%E9%98%B5%22%5D%20--%3E%20DAC%5B%22%E5%B1%9E%E4%B8%BB%E6%94%B9%20ACL%22%5D%0A%20%20MAT%20--%3E%20MAC%5B%22%E7%B3%BB%E7%BB%9F%E6%A0%87%E7%AD%BE%E7%AD%96%E7%95%A5%22%5D%0A%20%20MAT%20--%3E%20RBAC%5B%22%E8%A7%92%E8%89%B2%E8%81%9A%E5%90%88%E6%9D%83%E9%99%90%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"DAC 灵活、难防内部误授。MAC 服务机密性轴的强政策，可用性与兼容性代价高。RBAC 降的是管理复杂度，不是新的形式保证。后课能力把「行」发给主体当票。",-1)),(A(),o(s,null,{default:e(()=>[l(B,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E6%99%AE%E9%80%9A%E7%BA%A7%E7%94%A8%E6%88%B7%E8%BF%9B%E7%A8%8B%22%5D%20--%3E%7C%22%E8%AF%BB%E6%9C%BA%E5%AF%86%E7%BA%A7%22%7C%20X%5B%22%E6%8B%92%E7%BB%9D%EF%BC%9A%E4%B8%8D%E4%B8%8A%E8%AF%BB%22%5D%0A%20%20U%20--%3E%7C%22%E5%86%99%E5%85%AC%E5%BC%80%E7%BA%A7%22%7C%20Y%5B%22%E6%8B%92%E7%BB%9D%EF%BC%9A%E4%B8%8D%E4%B8%8B%E5%86%99%22%5D%0A%20%20U%20--%3E%7C%22%E8%AF%BB%E5%90%8C%E7%BA%A7%22%7C%20OK%5B%22%E6%94%BE%E8%A1%8C%22%5D%0A%20%20X%20--%3E%20EFF%5B%22%E6%9C%BA%E5%AF%86%E4%BF%A1%E6%81%AF%E8%A2%AB%E6%A0%87%E7%AD%BE%E5%9C%88%E4%BD%8F%EF%BC%8C%E6%B5%81%E4%B8%8D%E5%87%BA%E6%A0%BC%22%5D%0A%20%20Y%20--%3E%20EFF%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=E('<p><span class="marginnote">数字实例：500 名员工、8 种岗位、40 项权限。逐人授权要维护 500 份个人清单，岗位一变就得逐条找着改；RBAC 只维护 8 份角色定义加一条&quot;某人任某岗&quot;，离职时删一行角色指派就撤干净了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入基于属性的 ABAC 全貌当主干。矩阵按行发放不可伪造引用，下一课能力对 ACL。</p><p>后课默认：政策可来自属主、标签或角色。票与名单是两种表示。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DAC 属主做主；MAC 标签强制；RBAC 按岗位聚合。</li><li>引用监视器执行，不靠自愿遵守。</li><li>能力对照下一课。</li><li>出处：Lampson；Bell–LaPadula 对照；Sandhu RBAC；Saltzer and Schroeder。</li></ul>',6))])}const b=n(C,[["render",c]]);export{f as __pageData,b as default};
